const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};
const wfName = wf.name || "Unknown workflow";
const wfId = wf.id || "unknown";
const failedNode = err.node && err.node.name ? err.node.name : (ex.lastNodeExecuted || "unknown node");
const message = err.message || "No error message provided";
const mode = ex.mode || "unknown";
const when = ex.startedAt || new Date().toISOString();
const execUrl = ex.url || "";
const subject = `⚠️ Workflow failed: ${wfName} (${failedNode})`;
const lines = [
  `Workflow: ${wfName} (${wfId})`,
  `Failed node: ${failedNode}`,
  `Error: ${message}`,
  `Execution mode: ${mode}`,
  `Time: ${when}`,
];
if (execUrl) { lines.push(`Execution: ${execUrl}`); }
const body = lines.join("\n");
return [{ json: { subject, body, wfName, failedNode, message } }];
